  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }

 1→//! Shell reload resume state management.
 2→//!
 3→//! This module provides functionality for saving and restoring execution
 4→//! state across shell reloads.
 5→
 6→use anyhow::Result;
 7→use serde::{Deserialize, Serialize};
 8→use std::path::PathBuf;
 9→use std::sync::Mutex;
10→
11→// Override path for testing
12→static STATE_PATH_OVERRIDE: Mutex<Option<PathBuf>> = Mutex::new(None);
13→
14→/// State saved for resuming after shell reload.
15→///
16→/// # Example
17→///
18→/// ```no_run
19→/// use bivvy::shell::ResumeState;
20→/// use std::path::PathBuf;
21→///
22→/// // Create a resume state
23→/// let state = ResumeState {
24→///     project_root: PathBuf::from("/test/project"),
25→///     workflow: "default".to_string(),
26→///     completed_steps: vec!["step1".to_string()],
27→///     pending_step: "step2".to_string(),
28→///     timestamp: chrono::Utc::now(),
29→/// };
30→///
31→/// // Save state to disk
32→/// state.save().unwrap();
33→///
34→/// // Later, load state back
35→/// let loaded = ResumeState::load().unwrap().unwrap();
36→/// assert_eq!(loaded.workflow, "default");
37→/// ```
38→#[derive(Debug, Clone, Serialize, Deserialize)]
39→pub struct ResumeState {
40→    /// Project root path.
41→    pub project_root: PathBuf,
42→    /// Workflow being executed.
43→    pub workflow: String,
44→    /// Steps that have been completed.
45→    pub completed_steps: Vec<String>,
46→    /// Step that triggered the reload.
47→    pub pending_step: String,
48→    /// Timestamp when reload was requested.
49→    pub timestamp: chrono::DateTime<chrono::Utc>,
50→}
51→
52→impl ResumeState {
53→    /// Save resume state to disk.
54→    pub fn save(&self) -> Result<PathBuf> {
55→        let path = Self::state_path();
56→        if let Some(parent) = path.parent() {
57→            std::fs::create_dir_all(parent)?;
58→        }
59→        let content = serde_json::to_string_pretty(self)?;
60→        std::fs::write(&path, content)?;
61→        Ok(path)
62→    }
63→
64→    /// Load resume state if it exists.
65→    pub fn load() -> Result<Option<Self>> {
66→        let path = Self::state_path();
67→        if !path.exists() {
68→            return Ok(None);
69→        }
70→        let content = std::fs::read_to_string(&path)?;
71→        let state: Self = serde_json::from_str(&content)?;
72→        Ok(Some(state))
73→    }
74→
75→    /// Clear saved resume state.
76→    pub fn clear() -> Result<()> {
77→        let path = Self::state_path();
78→        if path.exists() {
79→            std::fs::remove_file(&path)?;
80→        }

  1→//! Version checking against latest release.
  2→
  3→use anyhow::{Context, Result};
  4→use chrono::{DateTime, Utc};
  5→use serde::{Deserialize, Serialize};
  6→use std::fs;
  7→use std::path::PathBuf;
  8→
  9→/// Current version of bivvy.
 10→pub const VERSION: &str = env!("CARGO_PKG_VERSION");
 11→
 12→/// GitHub API URL for releases.
 13→const GITHUB_API_URL: &str = "https://api.github.com/repos/bivvy-dev/bivvy/releases/latest";
 14→
 15→/// How often to check for updates (1 day).
 16→const CHECK_INTERVAL_SECS: i64 = 86400;
 17→
 18→/// Information about an available update.
 19→#[derive(Debug, Clone, Serialize, Deserialize)]
 20→pub struct UpdateInfo {
 21→    /// Current version.
 22→    pub current: String,
 23→    /// Latest available version.
 24→    pub latest: String,
 25→    /// Whether an update is available.
 26→    pub update_available: bool,
 27→    /// Release URL.
 28→    pub release_url: Option<String>,
 29→    /// When this check was performed.
 30→    pub checked_at: DateTime<Utc>,
 31→}
 32→
 33→/// Cached update check result.
 34→#[derive(Debug, Clone, Serialize, Deserialize)]
 35→struct UpdateCache {
 36→    /// Last update info.
 37→    info: UpdateInfo,
 38→    /// When the cache was written.
 39→    cached_at: DateTime<Utc>,
 40→}
 41→
 42→/// Check for available updates.
 43→///
 44→/// Returns cached result if within check interval.
 45→pub fn check_for_updates() -> Option<UpdateInfo> {
 46→    // Check cache first
 47→    if let Some(cached) = load_cache() {
 48→        let age = Utc::now()
 49→            .signed_duration_since(cached.cached_at)
 50→            .num_seconds();
 51→        if age < CHECK_INTERVAL_SECS {
 52→            return Some(cached.info);
 53→        }
 54→    }
 55→
 56→    // Fetch latest version
 57→    match fetch_latest_version() {
 58→        Ok(info) => {
 59→            // Cache the result
 60→            let _ = save_cache(&info);
 61→            Some(info)
 62→        }
 63→        Err(_) => {
 64→            // Return cached result even if expired
 65→            load_cache().map(|c| c.info)
 66→        }
 67→    }
 68→}
 69→
 70→/// Check for updates without using cache.
 71→pub fn check_for_updates_fresh() -> Result<UpdateInfo> {
 72→    fetch_latest_version()
 73→}
 74→
 75→/// Fetch the latest version from GitHub.
 76→fn fetch_latest_version() -> Result<UpdateInfo> {
 77→    let client = reqwest::blocking::Client::builder()
 78→        .user_agent("bivvy")
 79→        .timeout(std::time::Duration::from_secs(10))
 80→        .build()?;
 81→
 82→    let response: serde_json::Value = client
 83→        .get(GITHUB_API_URL)
 84→        .send()?
 85→        .json()
 86→        .context("Failed to parse GitHub API response")?;
 87→
 88→    let tag = response["tag_name"]
 89→        .as_str()
 90→        .context("No tag_name in response")?
 91→        .trim_start_matches('v');
 92→
 93→    let release_url = response["html_url"].as_str().map(String::from);
 94→
 95→    let update_available = is_newer_version(tag, VERSION);
 96→
 97→    Ok(UpdateInfo {
 98→        current: VERSION.to_string(),
 99→        latest: tag.to_string(),
100→        update_available,

100→        update_available,
101→        release_url,
102→        checked_at: Utc::now(),
103→    })
104→}
105→
106→/// Compare versions to check if `latest` is newer than `current`.
107→fn is_newer_version(latest: &str, current: &str) -> bool {
108→    let parse_version = |v: &str| -> Vec<u32> {
109→        v.split('.')
110→            .take(3)
111→            .filter_map(|s| s.parse().ok())
112→            .collect()
113→    };
114→
115→    let latest_parts = parse_version(latest);
116→    let current_parts = parse_version(current);
117→
118→    // Compare component by component
119→    for (l, c) in latest_parts.iter().zip(current_parts.iter()) {
120→        if l > c {
121→            return true;
122→        }
123→        if l < c {
124→            return false;
125→        }
126→    }
127→
128→    // If all components equal, check if latest has more components
129→    latest_parts.len() > current_parts.len()
130→}
131→
132→/// Get the cache file path.
133→fn cache_path() -> Option<PathBuf> {
134→    dirs::cache_dir().map(|d| d.join("bivvy").join("update_check.json"))
135→}
136→
137→/// Load cached update info.
138→fn load_cache() -> Option<UpdateCache> {
139→    let path = cache_path()?;
140→    let content = fs::read_to_string(path).ok()?;
141→    serde_json::from_str(&content).ok()
142→}
143→
144→/// Save update info to cache.
145→fn save_cache(info: &UpdateInfo) -> Result<()> {
146→    let path = cache_path().context("No cache directory")?;
147→
148→    if let Some(parent) = path.parent() {
149→        fs::create_dir_all(parent)?;
150→    }
151→
152→    let cache = UpdateCache {
153→        info: info.clone(),
154→        cached_at: Utc::now(),
155→    };
156→
157→    let content = serde_json::to_string_pretty(&cache)?;
158→    fs::write(path, content)?;
159→
160→    Ok(())
161→}
162→
163→/// Clear the update check cache.
164→pub fn clear_cache() -> Result<()> {
165→    if let Some(path) = cache_path() {
166→        if path.exists() {
167→            fs::remove_file(path)?;
168→        }
169→    }
170→    Ok(())
171→}
