    use super::*;

    #[test]
    fn config_dir_uses_platform_config() {
        let path = config_dir().expect("config_dir should resolve");
        assert!(path.ends_with("bivvy"));
        // Must NOT contain ".bivvy" — that's the old hardcoded path
        let path_str = path.to_string_lossy();
        assert!(
            !path_str.contains(".bivvy"),
            "config_dir must not use dotfile path, got: {}",
