//! Platform-standard directory paths for Bivvy.
//!
//! Centralizes all user-level directory resolution using the [`dirs`] crate
//! so that Bivvy follows XDG Base Directory conventions on Linux and the
//! platform-native equivalents on macOS and Windows.
//!
//! | Purpose          | Linux                         | macOS                                  |
//! |------------------|-------------------------------|----------------------------------------|
//! | User config      | `~/.config/bivvy/`            | `~/Library/Application Support/bivvy/` |
//! | User data        | `~/.local/share/bivvy/`       | `~/Library/Application Support/bivvy/` |
//! | Cache            | `~/.cache/bivvy/`             | `~/Library/Caches/bivvy/`              |
//!
//! Project-local paths (`.bivvy/` inside a repo) are unchanged.

use std::path::PathBuf;

/// Returns the user-level config directory for Bivvy.
///
/// Used for the global `config.yml`.
///
/// Resolves to `$XDG_CONFIG_HOME/bivvy` on Linux, or the platform
/// equivalent via [`dirs::config_dir`].
pub fn config_dir() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("bivvy"))
}

/// Returns the user-level data directory for Bivvy.
///
/// Used for templates, project state, and failure reports.
///
/// Resolves to `$XDG_DATA_HOME/bivvy` on Linux, or the platform
/// equivalent via [`dirs::data_dir`].
pub fn data_dir() -> Option<PathBuf> {
    dirs::data_dir().map(|d| d.join("bivvy"))
}

/// Returns the user-level cache directory for Bivvy.
///
/// Used for cached remote templates and update checks.
///
/// Resolves to `$XDG_CACHE_HOME/bivvy` on Linux, or the platform
/// equivalent via [`dirs::cache_dir`].
pub fn cache_dir() -> Option<PathBuf> {
    dirs::cache_dir().map(|d| d.join("bivvy"))
}

/// Returns the path to the user's global config file.
///
/// This is `config_dir()/config.yml`.
pub fn user_config_file() -> Option<PathBuf> {
    config_dir().map(|d| d.join("config.yml"))
}

/// Returns the path to user-level templates.
///
/// This is `data_dir()/templates`.
pub fn user_templates_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("templates"))
}

/// Returns the directory where project state is stored.
///
/// This is `data_dir()/projects`.
pub fn projects_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("projects"))
}

/// Returns the path to the project index file.
///
/// This is `data_dir()/projects/index.yml`.
pub fn project_index_file() -> Option<PathBuf> {
    data_dir().map(|d| d.join("projects").join("index.yml"))
}

/// Returns the directory for failure telemetry reports.
///
/// This is `data_dir()/failure-reports`.
pub fn failure_reports_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("failure-reports"))
}

/// Returns the cache directory for remote templates.
///
/// This is `cache_dir()/templates`.
pub fn template_cache_dir() -> Option<PathBuf> {
    cache_dir().map(|d| d.join("templates"))
}

